const D = { scale:1, energy:.6, bands:9, speed:1, twist:.6, density:.5, hue:280, x:.5, y:.5, style:'membrane', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width,height), cx=width*P.x, cy=height*P.y, t=K.t, sty=P.style;
const hsh = i => { const s = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return s - Math.floor(s); };
const nb = Math.max(4, Math.min(16, Math.round(P.bands)));
const M = Math.max(8, Math.min(16, Math.round(9 + P.density*6)));
const Ri = 0.10*u*P.scale, Ro = 0.44*u*P.scale;
const W = (0.055 + 0.05*P.energy)*u*P.scale;
const rot1 = t*(0.10 + P.speed*0.14), rot2 = t*(0.061 + P.speed*0.09)+1.3;
const twT = (1 + P.twist*2.0)*Math.PI;
const bass = Math.min(0.5, A.bass*0.6);

if (sty==='blueprint') background(214,58,17);
else if (sty==='engraving') background(34,10,56);
else background(258,42,8);

// soft central glow so the hole is not dead-black
noStroke();
for (let g=3;g>0;g--){ fill((P.hue+20)%360, 40, 8+5*g, 8); ellipse(cx,cy, Ro*2.1*(g/3), Ro*2.1*(g/3)); }

// faint nested Seifert circles behind
noFill();
for (let s=0;s<3;s++){
  const rr = Ri + (Ro-Ri)*((s+0.5)/3);
  stroke((P.hue+40)%360, 30, sty==='engraving'?26:34, 26*(P.alpha/100)); strokeWeight(1.4);
  const seg=48;
  beginShape();
  for(let a=0;a<=seg;a++){ const an=a/seg*Math.PI*2 + rot2*(s%2?-1:1); vertex(cx+rr*Math.cos(an), cy+rr*Math.sin(an)); }
  endShape();
}

function faceCol(shade, tw){
  const front = Math.cos(tw) >= 0;
  if (sty==='iridescent'){ return [(P.hue + 120*Math.sin(tw)+360)%360, 70, 30+55*shade, 74]; }
  if (sty==='engraving'){ return [30, 12, front? (24+40*shade) : (14+20*shade), 90]; }
  if (sty==='blueprint'){ return [ front?198:210, 55, 26+40*shade, 60]; }
  const h = front ? P.hue : (P.hue+40)%360;
  const v = (front? 34 : 20) + 46*shade + 12*bass;
  return [h, front?58:66, v, 80];
}

for (let k=0;k<nb;k++){
  const phi = k/nb*Math.PI*2 + rot1;
  const lean = 0.5*Math.sin(phi*2 + t*0.2); // slight spiral lean per band
  let prev=null;
  for (let i=0;i<=M;i++){
    const s = i/M;
    const ang = phi + lean*s*0.6;
    const rad = Ri + (Ro-Ri)*s;
    const px = cx + rad*Math.cos(ang), py = cy + rad*Math.sin(ang);
    const tw = twT*s + rot2 + phi*0.5;
    const tx = -Math.sin(ang), ty = Math.cos(ang); // tangential (ribbon width dir)
    const half = W*Math.cos(tw);
    const cur = { ax:px+tx*half, ay:py+ty*half, bx:px-tx*half, by:py-ty*half, tw };
    if (prev){
      const shade = Math.max(0, Math.min(1, 0.5+0.5*Math.cos((prev.tw+cur.tw)*0.5)*Math.SQRT1_2 + 0.3*Math.sin((prev.tw+cur.tw)*0.5)));
      const fc = faceCol(shade, (prev.tw+cur.tw)*0.5);
      if (sty==='xray'){
        noFill(); stroke((P.hue+30)%360,50,40+40*shade,55*(P.alpha/100)); strokeWeight(1.2);
        line(prev.ax,prev.ay,cur.ax,cur.ay); line(prev.bx,prev.by,cur.bx,cur.by);
      } else {
        noStroke(); fill(fc[0],fc[1],fc[2], fc[3]*(P.alpha/100));
        beginShape(); vertex(prev.ax,prev.ay); vertex(prev.bx,prev.by); vertex(cur.bx,cur.by); vertex(cur.ax,cur.ay); endShape(CLOSE);
        if (sty==='engraving'){ // hatch the face
          stroke(30,14,12,40*(P.alpha/100)); strokeWeight(0.8);
          const hn=3; for(let hgt=1;hgt<=hn;hgt++){ const f=hgt/(hn+1); line(prev.ax+(prev.bx-prev.ax)*f, prev.ay+(prev.by-prev.ay)*f, cur.ax+(cur.bx-cur.ax)*f, cur.ay+(cur.by-cur.ay)*f); }
        }
      }
    }
    prev = cur;
  }
  // ribbon edge strands (the boundary of the surface)
  noFill(); strokeCap(ROUND);
  const ecol = sty==='engraving'?[30,20,18]:sty==='blueprint'?[196,30,90]:[(P.hue+10)%360,30,90];
  for (let side=0; side<2; side++){
    stroke(ecol[0],ecol[1],ecol[2], 70*(P.alpha/100)); strokeWeight(1.6);
    beginShape();
    for (let i=0;i<=M;i++){ const s=i/M, ang=phi+lean*s*0.6, rad=Ri+(Ro-Ri)*s; const tw=twT*s+rot2+phi*0.5; const tx=-Math.sin(ang),ty=Math.cos(ang); const half=W*Math.cos(tw)*(side?-1:1); vertex(cx+rad*Math.cos(ang)+tx*half, cy+rad*Math.sin(ang)+ty*half); }
    endShape();
  }
}
